-- Chargeback approval allocates an existing cost; it never creates another payable or moves money.
CREATE TABLE tt_work_chargebacks(id TEXT PRIMARY KEY,tenancy_id TEXT NOT NULL REFERENCES tt_tenancies(id),source_id TEXT NOT NULL REFERENCES tt_journal(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),day TEXT NOT NULL,terms TEXT NOT NULL CHECK(json_valid(terms)),sha256 TEXT NOT NULL,prepared_by TEXT NOT NULL,prepared_at TEXT NOT NULL);
CREATE TABLE tt_work_chargeback_approvals(chargeback_id TEXT PRIMARY KEY REFERENCES tt_work_chargebacks(id),approved_by TEXT NOT NULL,approved_at TEXT NOT NULL,label TEXT);
INSERT INTO tt_role_actions(role,action) SELECT role,'chargeback.prepare' FROM tt_role_actions WHERE action='bill.create';
INSERT INTO tt_role_actions(role,action) SELECT role,'chargeback.approve' FROM tt_role_actions WHERE action='bill.approve';
CREATE TRIGGER tt_chargeback_kept BEFORE DELETE ON tt_work_chargebacks BEGIN SELECT RAISE(ABORT,'Chargeback accounting is retained'); END;
CREATE TRIGGER tt_chargeback_fixed BEFORE UPDATE ON tt_work_chargebacks WHEN NOT(NEW.id=OLD.id AND NEW.tenancy_id=OLD.tenancy_id AND NEW.source_id=OLD.source_id AND NEW.amount_cents=OLD.amount_cents AND NEW.day=OLD.day AND NEW.sha256=OLD.sha256 AND NEW.prepared_by=OLD.prepared_by AND NEW.prepared_at=OLD.prepared_at AND EXISTS(SELECT 1 FROM tt_erasure_work WHERE tenancy_id=OLD.tenancy_id)) BEGIN SELECT RAISE(ABORT,'Chargeback terms are immutable'); END;
CREATE TRIGGER tt_chargeback_approval_kept BEFORE DELETE ON tt_work_chargeback_approvals BEGIN SELECT RAISE(ABORT,'Chargeback approval is retained'); END;
CREATE TRIGGER tt_chargeback_approval_fixed BEFORE UPDATE ON tt_work_chargeback_approvals BEGIN SELECT RAISE(ABORT,'Chargeback approval is immutable'); END;
CREATE TRIGGER tt_chargeback_bill_frozen BEFORE UPDATE OF version,state,vendor_id,day ON tt_bills WHEN EXISTS(SELECT 1 FROM tt_work_chargebacks c JOIN tt_journal j ON j.id=c.source_id JOIN tt_bill_expenses x ON x.id=j.source_id WHERE j.source_kind='bill' AND x.bill_id=OLD.id) BEGIN SELECT RAISE(ABORT,'CHECK constraint: chargeback source payable is frozen'); END;
CREATE TRIGGER tt_chargeback_recovery_limit BEFORE INSERT ON tt_work_chargeback_approvals WHEN (SELECT SUM(c.amount_cents) FROM tt_work_chargebacks c WHERE c.id=NEW.chargeback_id OR (c.source_id=(SELECT source_id FROM tt_work_chargebacks WHERE id=NEW.chargeback_id) AND EXISTS(SELECT 1 FROM tt_work_chargeback_approvals a WHERE a.chargeback_id=c.id)))>(SELECT SUM(json_extract(l.value,'$.debit')) FROM tt_journal j,json_each(j.lines) l WHERE j.id=(SELECT source_id FROM tt_work_chargebacks WHERE id=NEW.chargeback_id) AND json_extract(l.value,'$.account')='expense') BEGIN SELECT RAISE(ABORT,'CHECK constraint: duplicate recovery'); END;
